fn is_palindrome(text: Vec<char>) -> bool {
    let mut left = 0;
    let mut right = text.len().saturating_sub(1); // Handle empty vector case

    while left < right {
        // Get the left character and convert to lowercase if it's an uppercase letter
        let left_char = text[left].to_ascii_lowercase();
        // Get the right character and convert to lowercase if it's an uppercase letter
        let right_char = text[right].to_ascii_lowercase();

        // Compare the characters
        if left_char != right_char {
            return false; // Not a palindrome
        }

        // Move the pointers
        left += 1;
        right = right.saturating_sub(1); // Prevent underflow
    }

    true // All characters matched, it's a palindrome
}